import{_ as a,a0 as d,w as p,s as r,I as n,x as i,a1 as e,A as o,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"調整你的 Git 配置以適應多個用户 ID 的需要 | LCTT x X-CMD","titleTemplate":false,"description":"調整你的 Git 配置以適應多個用户 ID 的需要 | LCTT (202011) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"調整你的 Git 配置以適應多個用户 ID 的需要 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"調整你的 Git 配置以適應多個用户 ID 的需要 | LCTT (202011) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202011/20201105 Tweak your Git config for multiple user IDs","title":"調整你的 Git 配置以適應多個用户 ID 的需要","tag":"202011","desc":""},"relativePath":"202011/20201105 Tweak your Git config for multiple user IDs.md","filePath":"[post].md"}'),u={name:"202011/20201105 Tweak your Git config for multiple user IDs.md"};function g(f,t,m,k,T,b){const s=d("Link");return p(),r("div",null,[t[31]||(t[31]=n("h1",{id:"調整你的-git-配置以適應多個用户-id-的需要",tabindex:"-1"},[i("調整你的 Git 配置以適應多個用户 ID 的需要 "),n("a",{class:"header-anchor",href:"#調整你的-git-配置以適應多個用户-id-的需要","aria-label":"Permalink to “調整你的 Git 配置以適應多個用户 ID 的需要”"},"​")],-1)),t[32]||(t[32]=n("blockquote",null,[n("p",null,"可以使用相同的機器用於工作和個人的 Git 提交，而無需手動重置你的配置。")],-1)),t[33]||(t[33]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202011/12/013805t4u4nu57rc6ur7nt.jpg",alt:""})],-1)),n("p",null,[t[1]||(t[1]=i("Git 的 ",-1)),e(s,{href:"https://git-scm.com/docs/git-config"},{default:o(()=>[...t[0]||(t[0]=[i("git config",-1)])]),_:1}),t[2]||(t[2]=i(" 命令可以讓你為 Git 設置倉庫或全局選項。它有很多選項，其中的一個選項 ",-1)),t[3]||(t[3]=n("code",null,"includeIf",-1)),t[4]||(t[4]=i(" 在你使用在 Git 時有雙重角色時非常方便，比如説，你既是全職的開發者，又在業餘時間為開源項目做貢獻。在這種情況下，大多數人都不想為兩個角色使用一個共同的配置，或者，至少，他們肯定希望保持配置的某些部分是不同的，尤其是當他們在兩個角色中使用同一台計算機時。",-1))]),t[34]||(t[34]=l(`<p>我的情況就是這樣，所以我在 Git 配置中保留了兩組不同的郵件 ID。這樣一來，在我工作場所的項目倉庫中提交的內容就會使用我辦公室的郵件 ID，而在我個人 GitHub 帳户中提交的內容則使用我個人的郵件 ID。</p><p>以下是我的全局配置（維護在 <code>$HOME/.gitconfig</code>）中的一個片段，我將在下文中介紹。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[includeIf &quot;gitdir:~/priv_scm/&quot;]</span></span>
<span class="line"><span>        path = ~/priv_scm/.gitconfig</span></span>
<span class="line"><span>[includeIf &quot;gitdir:~/work_scm/&quot;]</span></span>
<span class="line"><span>        path = ~/work_scm/.gitconfig</span></span></code></pre></div><h3 id="什麼是-includeif" tabindex="-1">什麼是 includeIf？ <a class="header-anchor" href="#什麼是-includeif" aria-label="Permalink to “什麼是 includeIf？”">​</a></h3><p><code>includeIf.condition.path</code> 變量，是 <code>include</code> 配置指令的一部分，允許你有條件地設置自定義配置。同時，自定義配置的路徑也可以作為指令的一部分來設置。</p>`,5)),n("p",null,[t[6]||(t[6]=i("這個指令支持三個關鍵字：",-1)),t[7]||(t[7]=n("code",null,"gitdir",-1)),t[8]||(t[8]=i("、",-1)),t[9]||(t[9]=n("code",null,"gitdir/I",-1)),t[10]||(t[10]=i(" 和 ",-1)),t[11]||(t[11]=n("code",null,"onbranch",-1)),t[12]||(t[12]=i("。我將簡單解釋一下 ",-1)),t[13]||(t[13]=n("code",null,"gitdir",-1)),t[14]||(t[14]=i("，我在上面的代碼片段中使用了它。你可以在",-1)),e(s,{href:"https://git-scm.com/docs/git-config#_conditional_includes"},{default:o(()=>[...t[5]||(t[5]=[i("文檔",-1)])]),_:1}),t[15]||(t[15]=i("中瞭解其他兩個關鍵詞。",-1))]),t[35]||(t[35]=l(`<p>在 <code>includeIf</code> 指令中使用 <code>gitdir</code> 關鍵字會對模式進行條件檢查。根據規則，如果當前工作目錄與 <code>gitdir</code> 中指定的目錄模式相匹配，那麼它就會從給定的路徑中選取配置。我將在配置片段上應用這個規則來展示它是如何被應用的。</p><p>在配置片段中，你可以看到一個簡單的模式，<code>~/</code>，它與 <code>gitdir</code> 關鍵字一起使用。這個模式會被存儲在 <code>$HOME</code> 環境變量中的值所替代。</p><h3 id="如何使用它" tabindex="-1">如何使用它 <a class="header-anchor" href="#如何使用它" aria-label="Permalink to “如何使用它”">​</a></h3><p>如果你使用同一個系統在 GitHub 或 GitLab 上的開源項目上工作，並在工作中提交到 Git 倉庫，你可以有兩個頂級目錄，比如 <code>$HOME/priv_scm</code> 和 <code>$HOME/work_scm</code>。在這兩個目錄中，你可以有兩個單獨的 <code>.gitconfig</code> 文件，其中包含與你的 <code>user.name</code> 和 <code>user.email</code> 相關的設置。然而，它們也可以包含存儲在 <code>$HOME</code> 的全局 <code>.gitconfig</code> 中，它可以保存兩個環境通用的所有自定義項。</p><p>這裏是一個例子 <code>$HOME/priv_scm/.gitconfig</code> 的片段：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat $HOME/priv_scm/.gitconfig</span></span>
<span class="line"><span>[user]</span></span>
<span class="line"><span>    name  = Ramanathan Muthiah</span></span>
<span class="line"><span>    email = &amp;lt;personal-mailid-goes-here&amp;gt;</span></span></code></pre></div><p>有了這個配置，你就可以切換目錄，並開始在開源項目上工作，而無需手動重置一些與 Git 相關的配置。這些更改會在主 <code>.gitconfig</code> 中藉助 <code>includeIf</code> 條件指令自動處理。</p><h3 id="git-小貼士" tabindex="-1">Git 小貼士 <a class="header-anchor" href="#git-小貼士" aria-label="Permalink to “Git 小貼士”">​</a></h3><p>希望這個小貼士能幫助你組織 Git 項目。你最喜歡的 Git 小貼士是什麼？請在評論中分享吧！</p><hr>`,10)),n("p",null,[t[17]||(t[17]=i("via: ",-1)),e(s,{href:"https://opensource.com/article/20/10/git-config"},{default:o(()=>[...t[16]||(t[16]=[i("https://opensource.com/article/20/10/git-config",-1)])]),_:1})]),n("p",null,[t[22]||(t[22]=i("作者：",-1)),e(s,{href:"https://opensource.com/users/muthiahramanathan"},{default:o(()=>[...t[18]||(t[18]=[i("Ramanathan M",-1)])]),_:1}),t[23]||(t[23]=i(" 選題：",-1)),e(s,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[19]||(t[19]=[i("lujun9972",-1)])]),_:1}),t[24]||(t[24]=i(" 譯者：",-1)),e(s,{href:"https://github.com/geekpi"},{default:o(()=>[...t[20]||(t[20]=[i("geekpi",-1)])]),_:1}),t[25]||(t[25]=i(" 校對：",-1)),e(s,{href:"https://github.com/wxy"},{default:o(()=>[...t[21]||(t[21]=[i("wxy",-1)])]),_:1})]),n("p",null,[t[28]||(t[28]=i("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[26]||(t[26]=[i("LCTT",-1)])]),_:1}),t[29]||(t[29]=i(" 原創編譯，",-1)),e(s,{href:"https://linux.cn/"},{default:o(()=>[...t[27]||(t[27]=[i("Linux中國",-1)])]),_:1}),t[30]||(t[30]=i(" 榮譽推出",-1))])])}const c=a(u,[["render",g]]);export{C as __pageData,c as default};
